using System;
using System.Collections.Generic;
using System.IO;
using Oumijia.Core.Classification;
using Oumijia.Core.Edz;
using Xunit;

namespace Oumijia.Core.Tests;

/// <summary>
/// Integration check against the synthetic example packages committed under
/// /examples (generated by tools/make-samples.ps1). Verifies end-to-end that
/// real files on disk are read and classified as intended.
/// </summary>
public class ExamplesIntegrationTests
{
    private static readonly Dictionary<string, (string Manufacturer, string Category)> Expected =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["ABB_S201-C16.edz"] = ("ABB", "MCB"),
            ["Siemens_3RT2024-1AL20.edz"] = ("Siemens", "Contactor"),
            ["Schneider_LC1D18BD.edz"] = ("Schneider Electric", "Contactor"),
            ["Phoenix_QUINT-PS-100-240AC-24DC-10.edz"] = ("Phoenix Contact", "PSU"),
            ["Siemens_6ES7214-1AG40-0XB0.edz"] = ("Siemens", "PLC"),
            ["Weidmueller_WDU-2-5.edz"] = ("Weidmüller", "Terminal"),
            ["Rittal_AE-1039-500.edz"] = ("Rittal", "Enclosure")
        };

    [Fact]
    public void Reads_and_classifies_all_committed_example_packages()
    {
        var examplesDir = FindExamplesDirectory();
        if (examplesDir == null) return; // examples folder not present; nothing to verify

        var classifier = new Classifier(ClassifierRules.CreateDefault());

        foreach (var pair in Expected)
        {
            var path = Path.Combine(examplesDir, pair.Key);
            if (!File.Exists(path)) continue; // partial checkout; skip missing files

            var info = EdzPackageReader.Read(path);
            Assert.NotNull(info.PrimaryManufacturer);

            var result = classifier.Classify(path, info);
            Assert.Equal(pair.Value.Manufacturer, result.ManufacturerFolder);
            Assert.Equal(pair.Value.Category, result.CategoryFolder);
        }
    }

    private static string? FindExamplesDirectory()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        for (var i = 0; i < 10 && dir != null; i++)
        {
            var candidate = Path.Combine(dir.FullName, "examples");
            if (Directory.Exists(candidate) && Directory.GetFiles(candidate, "*.edz").Length > 0)
            {
                return candidate;
            }
            dir = dir.Parent;
        }
        return null;
    }
}
